SELECT CASE WHEN shipping_fee >= 31 THEN 'high' WHEN shipping_fee >= 12 THEN 'mid' ELSE 'low' END AS shipping_fee_bucket, SUM(discount) AS total_discount, SUM(SUM(discount)) OVER (ORDER BY CASE WHEN shipping_fee >= 31 THEN 'high' WHEN shipping_fee >= 12 THEN 'mid' ELSE 'low' END) AS cumulative_discount FROM orders GROUP BY CASE WHEN shipping_fee >= 31 THEN 'high' WHEN shipping_fee >= 12 THEN 'mid' ELSE 'low' END ORDER BY total_discount ASC, cumulative_discount DESC, shipping_fee_bucket ASC LIMIT 1
